import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

// Create axios instance with auth header
const api = axios.create({
  baseURL: "http://localhost:8000",
});

// Add interceptor to include token in requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

function ProfilePage() {
  const navigate = useNavigate();
  const [profile, setProfile] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [message, setMessage] = useState("");

  // Check authentication on component mount
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/login");
      return;
    }
    
    fetchProfile();
  }, [navigate]);

  const fetchProfile = async () => {
    setIsLoading(true);
    try {
      const res = await api.get("/profile");
      setProfile(res.data);
    } catch (err) {
      console.error("Error fetching profile:", err);
      if (err.response?.status === 401) {
        // Token expired or invalid
        localStorage.removeItem("token");
        navigate("/login");
      } else {
        setMessage("Error loading profile information.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const goToOCR = () => {
    navigate("/ocr");
  };

  const goToBills = () => {
    navigate("/bills");
  };

  const goToOCRSpaceUpload = () => {
    navigate("/ocr-space-upload");
  };

  // Loading spinner component
  const LoadingSpinner = () => (
    <div className="loading-spinner">
      <div className="spinner"></div>
    </div>
  );

  return (
    <div className="container">
      {/* Header */}
      <div className="profile-header">
        <h1 className="app-title">User Profile</h1>
        <div className="header-buttons">
          <button className="btn btn-primary" onClick={goToBills}>
            Process Bill (OCR)
          </button>
          <button className="btn btn-success" onClick={goToGoogleVisionUpload}>
            🔍 Google Vision Upload
          </button>
          <button className="btn btn-danger" onClick={logout}>
            Logout
          </button>
        </div>
      </div>

      {/* Profile Content */}
      <div className="profile-content">
        {isLoading ? (
          <div className="loading-container">
            <LoadingSpinner />
            <p>Loading profile...</p>
          </div>
        ) : profile ? (
          <div className="profile-info">
            <div className="profile-card">
              <div className="profile-avatar">
                {profile.name ? profile.name.charAt(0).toUpperCase() : 
                 profile.username ? profile.username.charAt(0).toUpperCase() : 
                 profile.email ? profile.email.charAt(0).toUpperCase() : '?'}
              </div>
              
              <div className="profile-details">
                {profile.name && (
                  <div className="profile-field">
                    <label>Name:</label>
                    <span>{profile.name}</span>
                  </div>
                )}
                
                {profile.username && (
                  <div className="profile-field">
                    <label>Username:</label>
                    <span>{profile.username}</span>
                  </div>
                )}
                
                {profile.email && (
                  <div className="profile-field">
                    <label>Email:</label>
                    <span>{profile.email}</span>
                  </div>
                )}
                
                <div className="profile-field">
                  <label>Authentication Type:</label>
                  <span className={`auth-type ${profile.auth_type}`}>
                    {profile.auth_type === 'google' ? 'Google Account' : 'Regular Account'}
                  </span>
                </div>
                
                {profile.created_at && (
                  <div className="profile-field">
                    <label>Member Since:</label>
                    <span>{new Date(profile.created_at).toLocaleDateString()}</span>
                  </div>
                )}
              </div>
            </div>

            <div className="profile-actions">
              <button className="btn btn-primary btn-large" onClick={goToBills}>
                🧾 Process Travel Bills
              </button>
              <button className="btn btn-secondary btn-large" onClick={goToOCR}>
                🔍 OCR Text Extraction
              </button>
            </div>
          </div>
        ) : (
          <div className="error-container">
            <p>Unable to load profile information.</p>
            <button className="btn btn-primary" onClick={fetchProfile}>
              Try Again
            </button>
          </div>
        )}
      </div>

      {/* Message Display */}
      {message && (
        <div className="message error">
          {message}
        </div>
      )}
    </div>
  );
}

export default ProfilePage;
